def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Bootstrapped PC ensemble (majority-vote MEC recovery).

    Run stable-PC (chi-squared CI test) once on the full sample and on
    bootstrap resamples (identical integer encoding across all runs, so
    the "discretization" is shared/fixed). Vote on skeleton edges and
    edge orientations across runs; keep majority edges, take the
    majority orientation, then complete orientations with Meek rules.
    """
    import time
    from causallearn.graph.Edge import Edge
    from causallearn.graph.Endpoint import Endpoint
    from causallearn.utils.PCUtils import SkeletonDiscovery, Meek, UCSepset
    from causallearn.utils.cit import CIT

    n, N = X.shape
    alpha = 0.05
    B = 20
    rng = np.random.RandomState(0)
    start = time.time()
    if N < 20:
        budget = 1200.0
    elif N < 50:
        budget = 2400.0
    else:
        budget = 8600.0

    def run_pc(data):
        cit = CIT(data, "chisq")
        cg1 = SkeletonDiscovery.skeleton_discovery(
            data, alpha, cit, stable=True,
            background_knowledge=None, verbose=False,
            show_progress=False, node_names=None,
        )
        cg2 = UCSepset.uc_sepset(cg1, 2, background_knowledge=None)
        cg = Meek.meek(cg2, background_knowledge=None)
        return cg.G.graph

    adj_votes = np.zeros((N, N))
    dir_votes = np.zeros((N, N))
    und_votes = np.zeros((N, N))
    runs = 0
    last_dur = 0.0
    for b in range(B):
        if b > 0 and (time.time() - start) + 1.6 * last_dur > budget:
            break
        t0 = time.time()
        data = X if b == 0 else X[rng.randint(n, size=n)]
        try:
            g = run_pc(data)
        except Exception:
            continue
        last_dur = time.time() - t0
        runs += 1
        for i in range(N):
            for j in range(i + 1, N):
                a, c = g[i, j], g[j, i]
                if a == 0 and c == 0:
                    continue
                adj_votes[i, j] += 1
                if a == -1 and c == -1:
                    und_votes[i, j] += 1
                elif a == -1 and c == 1:
                    dir_votes[i, j] += 1
                elif a == 1 and c == -1:
                    dir_votes[j, i] += 1

    if runs == 0:
        return GeneralGraph([GraphNode(f"X{i + 1}") for i in range(N)])

    thr = 0.5 * runs
    und = np.zeros((N, N), dtype=bool)
    dr = np.zeros((N, N), dtype=bool)
    for i in range(N):
        for j in range(i + 1, N):
            if adj_votes[i, j] >= thr:
                dij = dir_votes[i, j]
                dji = dir_votes[j, i]
                uij = und_votes[i, j]
                if dij > max(dji, uij):
                    dr[i, j] = True
                elif dji > max(dij, uij):
                    dr[j, i] = True
                else:
                    und[i, j] = und[j, i] = True

    # ---- Meek rules R1-R3 to propagate orientations on voted graph ----
    def adjacent(i, j):
        return und[i, j] or dr[i, j] or dr[j, i]

    changed = True
    while changed:
        changed = False
        for p in range(N):
            for q in range(p + 1, N):
                if not und[p, q]:
                    continue
                for (x, y) in ((p, q), (q, p)):
                    done = False
                    # R1: z -> x, x - y, z not adjacent to y  =>  x -> y
                    for z in range(N):
                        if z != y and dr[z, x] and not adjacent(z, y):
                            done = True
                            break
                    if not done:
                        # R2: x -> z -> y and x - y  =>  x -> y
                        for z in range(N):
                            if dr[x, z] and dr[z, y]:
                                done = True
                                break
                    if not done:
                        # R3: x-z1, x-z2, z1->y, z2->y, z1/z2 nonadjacent
                        zs = [z for z in range(N) if und[x, z] and dr[z, y]]
                        for ii in range(len(zs)):
                            for jj in range(ii + 1, len(zs)):
                                if not adjacent(zs[ii], zs[jj]):
                                    done = True
                                    break
                            if done:
                                break
                    if done:
                        dr[x, y] = True
                        und[x, y] = und[y, x] = False
                        changed = True
                        break

    nodes = [GraphNode(f"X{i + 1}") for i in range(N)]
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(i + 1, N):
            if dr[i, j]:
                G.add_edge(Edge(nodes[i], nodes[j], Endpoint.TAIL, Endpoint.ARROW))
            elif dr[j, i]:
                G.add_edge(Edge(nodes[j], nodes[i], Endpoint.TAIL, Endpoint.ARROW))
            elif und[i, j]:
                G.add_edge(Edge(nodes[i], nodes[j], Endpoint.TAIL, Endpoint.TAIL))
    return G
