import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Bootstrapped PC ensemble: run stable-PC (chi-squared CI test) on B
    bootstrap resamples of the data (same integer encoding = shared
    "discretizer" across all runs), collect majority votes on skeleton
    edges and plurality votes on orientations, then propagate with Meek
    rules. Voting recovers the MEC with a finite-sample safety margin.
    """
    from causallearn.graph.Edge import Edge
    from causallearn.graph.Endpoint import Endpoint
    from causallearn.utils.PCUtils import SkeletonDiscovery, Meek, UCSepset
    from causallearn.utils.cit import CIT

    rng = np.random.RandomState(0)
    n, p = X.shape
    alpha = 0.05

    # ensemble size adapted to network size (keeps within compute budget)
    if p <= 12:
        B = 40
    elif p <= 25:
        B = 25
    elif p <= 40:
        B = 15
    else:
        B = 10

    def run_pc(data):
        cit = CIT(data, "chisq")
        cg1 = SkeletonDiscovery.skeleton_discovery(
            data, alpha, cit, stable=True,
            background_knowledge=None, verbose=False,
            show_progress=False, node_names=None,
        )
        cg2 = UCSepset.uc_sepset(cg1, 2, background_knowledge=None)
        return Meek.meek(cg2, background_knowledge=None).G.graph

    adj_c = np.zeros((p, p))
    dir_c = np.zeros((p, p))   # dir_c[i, j]: votes for i -> j
    und_c = np.zeros((p, p))
    votes = 0
    for b in range(B):
        idx = rng.randint(0, n, size=n)
        try:
            g = run_pc(np.ascontiguousarray(X[idx]))
        except Exception:
            continue
        votes += 1
        for i in range(p):
            for j in range(i + 1, p):
                e1, e2 = g[i, j], g[j, i]
                if e1 == 0 and e2 == 0:
                    continue
                adj_c[i, j] += 1
                if e2 == 1 and e1 == -1:      # i -> j
                    dir_c[i, j] += 1
                elif e1 == 1 and e2 == -1:    # j -> i
                    dir_c[j, i] += 1
                else:                         # undirected / bidirected
                    und_c[i, j] += 1

    A = np.zeros((p, p), dtype=int)  # A[i, j] = 1 means i -> j
    U = np.zeros((p, p), dtype=int)  # undirected (symmetric)

    if votes == 0:
        # fallback: single PC run on the full data
        g = run_pc(X)
        for i in range(p):
            for j in range(i + 1, p):
                e1, e2 = g[i, j], g[j, i]
                if e1 == 0 and e2 == 0:
                    continue
                if e2 == 1 and e1 == -1:
                    A[i, j] = 1
                elif e1 == 1 and e2 == -1:
                    A[j, i] = 1
                else:
                    U[i, j] = U[j, i] = 1
    else:
        thr = votes / 2.0
        for i in range(p):
            for j in range(i + 1, p):
                if adj_c[i, j] >= thr:
                    dij, dji, u = dir_c[i, j], dir_c[j, i], und_c[i, j]
                    if dij > dji and dij > u:
                        A[i, j] = 1
                    elif dji > dij and dji > u:
                        A[j, i] = 1
                    else:
                        U[i, j] = U[j, i] = 1

    def adjacent(a, b):
        return A[a, b] or A[b, a] or U[a, b]

    # Meek rules R1-R3 to propagate voted orientations consistently
    changed = True
    while changed:
        changed = False
        for a in range(p):
            for b in range(p):
                if not U[a, b]:
                    continue
                oriented = False
                # R1: c -> a, a - b, c and b non-adjacent  =>  a -> b
                for c in range(p):
                    if c != b and A[c, a] and not adjacent(c, b):
                        oriented = True
                        break
                if not oriented:
                    # R2: a -> c -> b, a - b  =>  a -> b
                    for c in range(p):
                        if A[a, c] and A[c, b]:
                            oriented = True
                            break
                if not oriented:
                    # R3: a - c, a - d, c -> b, d -> b, c,d non-adjacent
                    for c in range(p):
                        if U[a, c] and A[c, b]:
                            for d in range(c + 1, p):
                                if U[a, d] and A[d, b] and not adjacent(c, d):
                                    oriented = True
                                    break
                        if oriented:
                            break
                if oriented:
                    A[a, b] = 1
                    U[a, b] = U[b, a] = 0
                    changed = True

    nodes = [GraphNode(f"X{i + 1}") for i in range(p)]
    G = GeneralGraph(nodes)
    for i in range(p):
        for j in range(p):
            if A[i, j]:
                G.add_edge(Edge(nodes[i], nodes[j],
                                Endpoint.TAIL, Endpoint.ARROW))
    for i in range(p):
        for j in range(i + 1, p):
            if U[i, j]:
                G.add_edge(Edge(nodes[i], nodes[j],
                                Endpoint.TAIL, Endpoint.TAIL))
    return G
